create table if not exists public.website_preview_sessions (id uuid primary key default gen_random_uuid(), restaurant_id uuid not null references public.restaurants(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, source_url text not null, preview jsonb not null default '{}'::jsonb, quality_score numeric, model text, created_at timestamptz not null default now());
create index if not exists website_preview_restaurant_idx on public.website_preview_sessions(restaurant_id,created_at desc);
alter table public.website_preview_sessions enable row level security;
create policy "website preview members access" on public.website_preview_sessions for all using (exists(select 1 from public.restaurants r join public.organization_members om on om.organization_id=r.organization_id where r.id=website_preview_sessions.restaurant_id and om.user_id=auth.uid())) with check (exists(select 1 from public.restaurants r join public.organization_members om on om.organization_id=r.organization_id where r.id=website_preview_sessions.restaurant_id and om.user_id=auth.uid()));
